// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        Reverter reverter = new Reverter();
        _tos[0] = address(reverter);
        vm.prank(from);
        bool ok;
        try c.transfer(from, address(reverter), _tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
